import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DJVIMu25.js";const g=JSON.parse('{"title":"Game Modes","description":"","frontmatter":{"title":"Game Modes"},"headers":[],"relativePath":"en/guides/games.md","filePath":"en/guides/games.md","lastUpdated":1786543805000}'),i={name:"en/guides/games.md"};function n(l,e,s,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="game-modes" tabindex="-1">Game Modes <a class="header-anchor" href="#game-modes" aria-label="Permalink to &quot;Game Modes&quot;">​</a></h1><h2 id="single-player-games-2048-minesweeper-whack-a-mole-bejeweled" tabindex="-1">Single-Player Games (2048 / Minesweeper / Whack-a-Mole / Bejeweled) <a class="header-anchor" href="#single-player-games-2048-minesweeper-whack-a-mole-bejeweled" aria-label="Permalink to &quot;Single-Player Games (2048 / Minesweeper / Whack-a-Mole / Bejeweled)&quot;">​</a></h2><p>Open <a href="./commands"><code>/gb</code></a> → pick a game → click <strong>Start Game</strong>. Scores are recorded to the <a href="./../reference/scoring">high-score table</a> automatically.</p><h2 id="lottery" tabindex="-1">Lottery <a class="header-anchor" href="#lottery" aria-label="Permalink to &quot;Lottery&quot;">​</a></h2><p>Classic numeric lottery, fully GUI-driven:</p><ol><li>Open <code>/gb</code> → pick <strong>Lottery</strong> → choose 4 digits (each in range 1–9).</li><li>Click the <strong>Draw</strong> button to take a weighted-random draw from the prize pool.</li><li>The prize pool supports tokens, coins (requires Vault), and console commands — all can be awarded together.</li></ol><p><strong>Editing Prizes (Admin GUI):</strong></p><ul><li>Entry: Run <a href="./commands"><code>/gba games</code></a> in-game, enter the <strong>Lottery</strong> management page → click the <strong>Prize Pool</strong> button; or click the prize-pool icon inside the <code>lottery</code> management GUI.</li><li>In the prize-pool editor you can: add new prizes, remove existing ones, adjust each prize&#39;s <strong>weight</strong> (larger = more likely), <strong>token reward</strong>, <strong>coin reward</strong>, and <strong>command reward</strong>.</li><li>Click <strong>Save</strong> to write the result to <code>plugins/JoyMart/games/lottery/config.yml</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The prize-pool format is shared with the Slot Machine and is documented under <a href="./configuration#lottery-slot-machine-prize-pool-config">Lottery / Slot Machine Prize Pool Config</a>.</p></div><h2 id="slot-machine" tabindex="-1">Slot Machine <a class="header-anchor" href="#slot-machine" aria-label="Permalink to &quot;Slot Machine&quot;">​</a></h2><p>Classic 3-reel slot machine; click the lever and the reels stop on random symbols:</p><ul><li>All three symbols match → jackpot (weighted-random pick from the prize pool)</li><li>Two symbols match → small prize (fixed token payout)</li><li>All different → no win</li><li>Prize-pool config is identical to the Lottery (same admin GUI entry).</li></ul><h2 id="maze" tabindex="-1">Maze <a class="header-anchor" href="#maze" aria-label="Permalink to &quot;Maze&quot;">​</a></h2><p>Each round generates a random 9×9 recursive-backtracking maze. Click an adjacent cell to move one step up/down/left/right toward the bottom-right exit:</p><ul><li>Visited cells turn green so you can review your path.</li><li>A timer records your completion time; the shorter the time, the larger the token reward.</li><li>Closing the GUI mid-game counts as giving up — no reward.</li><li>On completion, your best time is recorded to the high-score table.</li></ul><h2 id="snake" tabindex="-1">Snake <a class="header-anchor" href="#snake" aria-label="Permalink to &quot;Snake&quot;">​</a></h2><p>Classic Snake, auto-moving in a 9×5 two-inventory interface:</p><ul><li>Click the direction buttons (up/down/left/right) to steer the snake; you can&#39;t reverse directly.</li><li>Eating food (red apple) grows the snake by 1 and gives +10 score; new food spawns automatically.</li><li>Hitting a wall or yourself ends the game; filling the entire board counts as a win.</li><li>Pause/resume buttons supported; higher scores yield more tokens.</li></ul><h2 id="dino-run" tabindex="-1">Dino Run <a class="header-anchor" href="#dino-run" aria-label="Permalink to &quot;Dino Run&quot;">​</a></h2><p>Inspired by the Chrome offline dinosaur, a side-scrolling runner:</p><ul><li>The dino runs forward automatically; cacti scroll in from the right.</li><li>Click the jump button (3 cells wide for easy tapping) to leap over cacti.</li><li>+1 score per tick alive; higher scores shorten obstacle spacing (difficulty ramps up).</li><li>Hitting a cactus ends the game; the score equals your survival time.</li></ul><h2 id="chess" tabindex="-1">Chess <a class="header-anchor" href="#chess" aria-label="Permalink to &quot;Chess&quot;">​</a></h2><p>6×6 Los Alamos variant (no bishops), supports both two-player and AI play:</p><ul><li>White moves first; Player 1 plays White (bottom), Player 2 / AI plays Black (top).</li><li>Pieces: rook, knight, queen, king, knight, rook + 6 pawns (no bishops).</li><li>Click your own piece to select it (legal moves highlighted in green), then click the target cell to move.</li><li>Pawns auto-promote to queen at the last rank; check / checkmate / stalemate are detected.</li><li>A resign button ends the game at any time; checkmating your opponent wins.</li><li><strong>Two-player</strong>: Invite a friend to share the same board and take turns.</li><li><strong>AI</strong>: A two-ply minimax AI that prefers captures, blocks threats, and controls the center.</li></ul><h2 id="monopoly" tabindex="-1">Monopoly <a class="header-anchor" href="#monopoly" aria-label="Permalink to &quot;Monopoly&quot;">​</a></h2><p>A GUI recreation of the classic Monopoly board game. Supports <strong>2–3 players</strong> in the same session, plus a <strong>1 human + AI</strong> mode:</p><ul><li>A 26-space looped board is rendered around the perimeter of a 6×9 (54-slot) chest inventory; the center holds dice, player info, and action buttons.</li><li>Space types: GO (collect 200 on pass), Jail, Free Parking, Go To Jail; Chance and Community Chest spaces draw random cards; 17 buyable properties (Old Town, City Hall, Train Station, Airport, Skyscraper, Gold Mine, etc.).</li><li>Each turn: the current player clicks <strong>Roll Dice</strong> → a single die advances the token → landing on unowned land offers purchase, landing on someone else&#39;s property auto-deducts rent, landing on Chance/Chest draws a card → click <strong>End Turn</strong>.</li><li>A player whose balance hits zero is bankrupt and eliminated; the last non-bankrupt player wins.</li><li><strong>3-player-only betting</strong>: before the first roll, each player may bet on who will win; guessing correctly yields an extra reward.</li><li><strong>AI opponent</strong>: entering solo auto-fills an AI player that auto-buys properties, rolls, and ends its turn.</li><li>Rewards: win +10, draw +3, lose +2 tokens.</li></ul><h2 id="two-player-games-tic-tac-toe-connect-4-rock-paper-scissors-battleship-chess" tabindex="-1">Two-Player Games (Tic-Tac-Toe / Connect 4 / Rock-Paper-Scissors / Battleship / Chess) <a class="header-anchor" href="#two-player-games-tic-tac-toe-connect-4-rock-paper-scissors-battleship-chess" aria-label="Permalink to &quot;Two-Player Games (Tic-Tac-Toe / Connect 4 / Rock-Paper-Scissors / Battleship / Chess)&quot;">​</a></h2><p>Two-player games support two modes:</p><ol><li><p><strong>Invite a friend</strong> — Click <strong>Invite</strong>, type the target player&#39;s name in chat, and they&#39;ll receive a clickable invitation message (accept/decline). Once accepted, both players share the same game UI and take turns.</p></li><li><p><strong>Play against AI</strong> — Click <strong>Play AI</strong> to start immediately without waiting for an opponent. The AI moves automatically after 1 second:</p><ul><li><strong>Tic-Tac-Toe AI</strong>: Strategic — find a winning move → block the opponent → take the center → take a corner → random.</li><li><strong>Connect 4 AI</strong>: Strategic — find a winning column → block the opponent → prefer the middle column → random.</li><li><strong>Rock-Paper-Scissors AI</strong>: Random.</li><li><strong>Battleship AI</strong>: Randomly fires at un-attacked cells.</li><li><strong>Chess AI</strong>: Two-ply minimax — evaluates each move and the opponent&#39;s best reply, preferring captures, center control, and blocking threats.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>AI games also count toward the high-score table and token rewards. See <a href="./../reference/scoring">Scoring &amp; Events</a> for the full reward table.</p></div>',31)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
